create table public.learning_contents (id uuid primary key default gen_random_uuid(), competency_id uuid not null references public.competencies(id) on delete restrict, title text not null, content_type text not null, body text, configuration jsonb, sequence integer not null default 1 check (sequence > 0), status text not null default 'draft', created_by uuid not null references public.profiles(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
